{
  "lines": [
    {
      "key": "opening",
      "japanese": "あれ、〇〇じゃん！",
      "reading": "あれ、まるまるじゃん！",
      "romaji": "Are, marumaru jan! \n\n(Hey, it's you!)"
    },
    {
      "key": "reply",
      "japanese": "あ、久しぶり！元気だった？",
      "reading": "あ、ひさしぶり！げんきだった？",
      "romaji": "A, hisashiburi! Genki datta? \n\n(Oh, long time no see! How have you been?)"
    },
    {
      "key": "question",
      "japanese": "うん、まあまあかな。そっちは？",
      "reading": "うん、まあまあかな。そっちは？",
      "romaji": "Un, maa maa kana. Socchi wa? \n\n(Yeah, I'm okay. How about you?)"
    },
    {
      "key": "response",
      "japanese": "私も元気だよ。",
      "reading": "わたしもげんきだよ。",
      "romaji": "Watashi mo genki da yo. \n\n(I'm good too.)"
    },
    {
      "key": "suggestion",
      "japanese": "なんか、コーヒーでもどう？",
      "reading": "なんか、コーヒーでもどう？",
      "romaji": "Nanka, koohii demo dou? \n\n(How about we grab some coffee?)"
    },
    {
      "key": "agreement",
      "japanese": "いいね！行こう行こう。",
      "reading": "いいね！いこういこう。",
      "romaji": "Ii ne! Ikoo ikoo. \n\n(Sounds good! Let's go.)"
    }
  ]
}

